# Alexander's head: the head generated by Hunyuan3D (head/head_hunyuan.glb, placed by head_shape.py in build_uniform.py)
# itself - its geometry (hair, whiskers, moustache, ears) and its texture, colour-matched to the portrait - on the
# MPFB body, with face bones for blinking and talking.
# blender -b art/3d/alexander_leader.blend --python art/3d/build_head.py   (after build_uniform.py and build_details.py)
# Rewrites art/3d/alexander_leader.blend; safe to re-run (removes what it made before).
#  Head  - the generated head down to just under the chin (below it, its uniform's collar is cut off).
#  Neck  - MPFB's neck from inside the tunic's collar up into the head, skin-coloured.
#          Its mouth is slightly open; a dark cavity behind it ('Mouth') shows when the jaw drops.
# Face bones (children of 'head'): jaw, eye_l/r, lid_upper_l/r, lid_lower_l/r, lip_corner_l/r (MPFB 'default' rig
# joints; the lid and eye bones moved to the generated eyes). The eyes are painted: a blink turns the upper lid down
# about the eyeball centre by sc['head']['BLINK_DEG'], the weights grading from the upper rim to the lower one, so the
# painted eye folds away under the lid. Talking: jaw about X.
import bpy, bmesh, math, os, sys, json, colorsys
import numpy as np
from mathutils import Vector, Matrix
from mathutils.bvhtree import BVHTree
from mathutils.kdtree import KDTree

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import head_shape  # noqa: E402
OUT = os.path.join(HERE, 'alexander_leader.blend')
SKIN_TEX = os.path.join(HERE, 'textures', 'head_albedo.png')
PORTRAIT = os.path.join(HERE, 'head', 'head_input.png')  # what the head was generated from: its front view
HEAD_Z = 1.72                     # the head mesh ends here, inside the tunic's collar
RIM_FILL = (0.004, 0.016)         # skin within this of the cut's rim gives the neck its colour
CAP_SUBDIV = 2                    # rounds of splitting the cap under the jaw
RIM_SPIKES = 6                    # rounds of taking spikes off the rim
RIM_SMOOTH = 12                   # rounds of smoothing along the cut's rim
NECK_SKIRT = 0.025                # the bottom of the head drawn in onto the neck over this height
NECK_CUT = 0.016                  # the generated head ends this far under the chin (below: its uniform's collar)
HAIR_KEEP = 0.25                  # ... of the hair's (its red and orange blotches)
DELIGHT_IT = 6                    # smoothing rounds over the mesh for the baked light (~4 mm per round)
DELIGHT_CLAMP = (0.7, 2.2)        # the light taken out at most / at least
DELIGHT_HAIR = 0.6                # ... on the hair this much of it (its own dark gaps between curls stay a little)
CHROMA_KEEP = 0.5                 # colour match: this much of the generated texture's own colour variation stays
NECK_TUCK = 0.003                 # the neck's top inside the jaw
NECK_SHADE = 1.0                  # the neck: the jaw skin's colour times this
UNDER_EYE = (18, 60, 0.85)        # px under the lower rims: the generated skin's dark bags lightened, fading out
                                  # from the first to the second, by this much towards the skin's brightness
# The painted eyes and the lip line in head_input.png (px): outer and inner corners shared by both rims.
EYE_RIMS = {
    'l': {'upper': [(500, 433), (520, 420), (540, 416), (560, 416), (580, 422), (593, 433)],
          'lower': [(500, 433), (520, 435), (540, 441), (560, 441), (580, 438), (593, 433)]},
    'r': {'upper': [(323, 437), (335, 431), (350, 427), (365, 424), (380, 427), (390, 432), (395, 439)],
          'lower': [(323, 437), (335, 444), (350, 447), (365, 446), (380, 443), (390, 441), (395, 439)]},
}
LID_FADE = 22                     # px: the upper lid's skin above the rim follows less and less up to the brow
EYE_DEPTH = 0.011                 # eyeball centre (the lids' pivot) this far behind the eye opening
MOUTH_LINE = [(400, 618), (420, 615), (435, 617), (450, 618), (465, 617), (480, 616), (500, 617), (512, 620)]
MOUTH_CLOSE = 0.005               # the lower lip raised by this in the rest shape (the generated mouth is open)
CLOSE_FADE = (12, 60)             # px under the lip line: raised fully, not at all
JAW_FULL = 30                     # px: the lower lip this close under the cut follows the jaw fully
MOUTH_RGB = (0.10, 0.035, 0.03)
MOUTH_BACK = 0.006                # the cavity's front this far behind the lip line
FACE_RIG = {'jaw': 'jaw', 'eye_l': 'eye.L', 'eye_r': 'eye.R', 'lid_upper_l': 'orbicularis03.L',
            'lid_upper_r': 'orbicularis03.R', 'lid_lower_l': 'orbicularis04.L', 'lid_lower_r': 'orbicularis04.R',
            'lip_corner_l': 'risorius03.L', 'lip_corner_r': 'risorius03.R'}

sc = bpy.context.scene
h, rig = bpy.data.objects['Human'], bpy.data.objects['HumanRig']
for o in list(bpy.data.objects):
    if o.get('head_part'):
        bpy.data.objects.remove(o)
for n in ('hair_albedo', 'eye_albedo', 'gen_albedo', 'gen_hair'):
    if bpy.data.images.get(n):
        bpy.data.images.remove(bpy.data.images[n])
bones = {b.name for b in rig.data.bones} - set(head_shape.FACE_BONES)
smoothstep = head_shape.smoothstep

# ---------------------------------------------------------------- the fitted basemesh, helpers included
rig.data.pose_position = 'REST'
for m in h.modifiers:
    m.show_viewport = m.type != 'MASK'
dg = bpy.context.evaluated_depsgraph_get()
full = bpy.data.meshes.new_from_object(h.evaluated_get(dg), preserve_all_data_layers=True, depsgraph=dg)
for m in h.modifiers:
    m.show_viewport = True
rig.data.pose_position = 'POSE'
gnames = [g.name for g in h.vertex_groups]
gidx = {n: i for i, n in enumerate(gnames)}


def members(name, thr=0.5):
    i = gidx[name]
    return [v.index for v in full.vertices if any(g.group == i and g.weight > thr for g in v.groups)]


def new_object(name, bm, mat, groups=()):
    me = bpy.data.meshes.new(name); bm.to_mesh(me)
    ob = bpy.data.objects.new(name, me); sc.collection.objects.link(ob)
    ob['head_part'] = True
    me.materials.append(mat)
    for p in me.polygons:
        p.use_smooth = True
    for n in groups:
        ob.vertex_groups.new(name=n)
    ob.modifiers.new('Armature', 'ARMATURE').object = rig
    return ob


def material(name, tex_path=None, rough=0.6, rgb=None):
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    mat.use_nodes = True
    nt = mat.node_tree
    bsdf = next(n for n in nt.nodes if n.type == 'BSDF_PRINCIPLED')
    bsdf.inputs['Roughness'].default_value = rough
    if rgb:
        bsdf.inputs['Base Color'].default_value = (*rgb, 1)
    for n in [n for n in nt.nodes if n.type == 'TEX_IMAGE']:
        nt.nodes.remove(n)
    if tex_path:
        tex = nt.nodes.new('ShaderNodeTexImage')
        img = bpy.data.images.load(tex_path, check_existing=True); img.reload()
        tex.image = img
        nt.links.new(tex.outputs['Color'], bsdf.inputs['Base Color'])
    return mat


# ---------------------------------------------------------------- face bones
def joint(spec):
    if spec.get('cube_name'):
        ids = members(spec['cube_name'])
        return sum((full.vertices[i].co for i in ids), Vector()) / len(ids)
    if spec.get('vertex_index') is not None:
        return full.vertices[spec['vertex_index']].co.copy()
    if spec.get('vertex_indices'):
        return sum((full.vertices[i].co for i in spec['vertex_indices']), Vector()) / len(spec['vertex_indices'])
    return Vector(spec['default_position'])


def add_face_bones(eye_pivots, fwd):
    """MPFB 'default' rig joints; eye and lid bones at the generated eyes' centres, pointing forward."""
    from bl_ext.blender_org import mpfb
    rdef = json.load(open(os.path.join(os.path.dirname(mpfb.__file__), 'data', 'rigs', 'standard', 'rig.default.json')))
    bpy.context.view_layer.objects.active = rig
    for o in sc.objects:
        o.select_set(o == rig)
    bpy.ops.object.mode_set(mode='EDIT')
    eb = rig.data.edit_bones
    for name in head_shape.FACE_BONES:
        if eb.get(name):
            eb.remove(eb[name])
    for name, src in FACE_RIG.items():
        d = rdef[src]
        b = eb.new(name)
        if name.startswith(('eye_', 'lid_')):
            b.head = eye_pivots[name[-1]]
            b.tail = b.head + fwd * 0.012
            b.roll = 0.0
        else:
            b.head, b.tail = joint(d['head']), joint(d['tail'])
            if (b.tail - b.head).length < 0.005:
                b.tail = b.head + Vector((0, -0.01, 0))
            b.roll = d.get('roll', 0.0)
        b.parent = eb['head']
        b.use_deform = True
    bpy.ops.object.mode_set(mode='OBJECT')
    print('face bones:', ', '.join(FACE_RIG))


# ---------------------------------------------------------------- the generated head in place
T = Matrix([list(r) for r in sc['head']['T']])
CHIN_Z = sc['head']['CHIN_Z']
gbm, gimg, cls = head_shape.generated_placed([list(r) for r in T], CHIN_Z)
FWD = (T.to_3x3() @ Vector((0, -1, 0))).normalized()  # the portrait's view direction, reversed
puv = gbm.loops.layers.uv['proj']
CLS = gbm.faces.layers.int.new('cls')  # survives the edits below
UNIFORM = gbm.faces.layers.int.new('uniform')  # uniform-coloured (red, gold, navy, white shirt), wherever it is
for f, rgb in zip(gbm.faces, head_shape.face_colours(gbm, gimg)):
    f[CLS] = cls[f.index]
    hh_, ss_, vv_ = colorsys.rgb_to_hsv(*(min(1.0, max(0.0, float(c))) for c in rgb))
    f[UNIFORM] = int(head_shape.is_collar(hh_ * 360, ss_, vv_))
n0 = len(gbm.verts)
bmesh.ops.remove_doubles(gbm, verts=gbm.verts[:], dist=1e-6)  # glTF splits vertices along UV seams
print('generated head: %d -> %d verts' % (n0, len(gbm.verts)))


def img_points():
    """vert -> its point in head_input.png (px)."""
    return {l.vert: (l[puv].uv.x * 1024, (1 - l[puv].uv.y) * 1024) for f in gbm.faces for l in f.loops}


def is_hair(f):
    return f[CLS] == head_shape.HAIR


def is_skin(f):
    return f[CLS] == head_shape.SKIN


def front(v):
    return v.normal.dot(FWD) > 0.3


def interp(pts, x):
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if min(x0, x1) <= x <= max(x0, x1):
            return y0 + (y1 - y0) * (x - x0) / ((x1 - x0) or 1)
    return None


body = set(members('body'))
AXIS = Vector(sc['uniform']['NECK_AXIS'])
fb = bmesh.new(); fb.from_mesh(full)
fb.verts.ensure_lookup_table()
bmesh.ops.delete(fb, geom=[v for v in fb.verts if v.index not in body], context='VERTS')
BODY_BVH = BVHTree.FromBMesh(fb)  # MPFB's body: the neck the generated head is drawn onto
fb.free()


def drop_loose():
    """Pieces wholly under the chin (bits of the generated collar)."""
    seen, comps = set(), []
    for f in gbm.faces:
        if f in seen:
            continue
        comp, stack = [], [f]; seen.add(f)
        while stack:
            g = stack.pop(); comp.append(g)
            for e in g.edges:
                for k in e.link_faces:
                    if k not in seen:
                        seen.add(k); stack.append(k)
        comps.append(comp)
    for comp in comps:
        if all(f.calc_center_median().z < CHIN_Z for f in comp):
            bmesh.ops.delete(gbm, geom=comp, context='FACES')
    bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')


def cut_neck():
    """Under the chin the generated head is its uniform's collar and shirt: cut off by a plane NECK_CUT under the chin,
    and what is uniform-coloured under the jaw goes too. Then the bottom NECK_SKIRT of the sides and back is drawn in
    onto MPFB's neck (out from the neck's axis), fully at the cut: whiskers and nape hair meet the neck closely (see
    'Neck'); under the jaw, which faces down and would crumple, the opening is capped in the neck's material."""
    no = Vector((0, 0, 1))
    co = Vector((0, 0, CHIN_Z - NECK_CUT))
    bmesh.ops.delete(gbm, geom=[f for f in gbm.faces if f[CLS] == head_shape.COLLAR or (
        f[UNIFORM] and f.calc_center_median().z < CHIN_Z + 0.01) or (  # and the skin under the jaw (pale, ragged)
        f[CLS] == head_shape.SKIN and f.calc_center_median().z < CHIN_Z - 0.004)],
        context='FACES')
    bmesh.ops.bisect_plane(gbm, geom=gbm.verts[:] + gbm.edges[:] + gbm.faces[:], dist=1e-6,
                           plane_co=co, plane_no=no, clear_inner=True)
    bmesh.ops.triangulate(gbm, faces=[f for f in gbm.faces if len(f.verts) > 3])
    bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')
    drop_loose()
    gbm.normal_update()
    for _ in range(RIM_SPIKES):  # spikes along the rim (faces with two open edges) off, before it is smoothed
        spikes = [f for f in gbm.faces if sum(e.is_boundary for e in f.edges) >= 2
                  and all(v.co.z < CHIN_Z + 0.03 for v in f.verts)]
        if not spikes:
            break
        bmesh.ops.delete(gbm, geom=spikes, context='FACES')
        bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')
    rim = [e for e in gbm.edges if e.is_boundary and all(v.co.z < CHIN_Z + 0.03 for v in e.verts)]
    rv = {v for e in rim for v in e.verts}
    for _ in range(RIM_SMOOTH):  # the ragged rim smoothed along itself (the cap would show its teeth)
        new = {}
        for v in rv:
            ns = [e.other_vert(v) for e in v.link_edges if e.is_boundary]
            if len(ns) == 2:
                new[v] = v.co * 0.5 + (ns[0].co + ns[1].co) * 0.25
        for v, c in new.items():
            v.co = c
    for v in gbm.verts:
        # sides and back only: under the jaw the surface faces down, drawn in it would crumple (capped instead)
        k = (1 - smoothstep((v.co - co).dot(no), 0.0, NECK_SKIRT)) * smoothstep(v.normal.z, -0.7, -0.3)
        d = Vector((v.co.x - AXIS.x, v.co.y - AXIS.y, 0))
        if k <= 0 or d.length < 1e-4:
            continue
        hit = BODY_BVH.ray_cast(Vector((AXIS.x, AXIS.y, v.co.z)), d.normalized(), 0.3)
        if hit[0] is not None and hit[3] + 0.001 < d.length:  # only ever inwards
            v.co = v.co.lerp(hit[0] + d.normalized() * 0.001, k)
    gbm.normal_update()
    rim_co = [v.co.copy() for v in rv]
    # what is still open under the jaw: capped (the neck's material)
    cap = bmesh.ops.holes_fill(gbm, edges=[e for e in rim if e.is_valid], sides=0)['faces']
    cap = set(bmesh.ops.triangulate(gbm, faces=cap)['faces'])
    for f in cap:
        f[CLS] = head_shape.SKIN
        f.material_index = 1
        for l in f.loops:
            other = next((m for m in l.vert.link_loops if m.face not in cap), None)
            if other:
                l[puv].uv = other[puv].uv
    bmesh.ops.recalc_face_normals(gbm, faces=gbm.faces[:])
    print('neck cut: %d cap faces' % len(cap))
    global RIM_KD
    RIM_KD = KDTree(len(rim_co))
    for i, c in enumerate(rim_co):
        RIM_KD.insert(c, i)
    RIM_KD.balance()
    return co, no


CUT = cut_neck()


def refine():
    """The generated mesh is ~4 mm coarse - two rows across an eye: eyes and mouth subdivided (twice per edge)."""
    img = img_points()
    boxes = [(min(x for x, _ in r['upper']) - 15, min(y for _, y in r['upper']) - LID_FADE - 10,
              max(x for x, _ in r['upper']) + 15, max(y for _, y in r['lower']) + 15) for r in EYE_RIMS.values()]
    boxes.append((MOUTH_LINE[0][0] - 15, min(y for _, y in MOUTH_LINE) - 25, MOUTH_LINE[-1][0] + 15,
                  max(y for _, y in MOUTH_LINE) + 25))
    inside = lambda p: any(b[0] <= p[0] <= b[2] and b[1] <= p[1] <= b[3] for b in boxes)  # noqa: E731
    faces = [f for f in gbm.faces if any(inside(img[v]) for v in f.verts) and f.normal.dot(FWD) > 0]
    edges = list({e for f in faces for e in f.edges})
    bmesh.ops.subdivide_edges(gbm, edges=edges, cuts=2, use_grid_fill=True)
    bmesh.ops.triangulate(gbm, faces=gbm.faces[:])
    gbm.normal_update()
    print('refined %d faces' % len(faces))


# ---------------------------------------------------------------- texture: the generated one, coloured like the portrait
portrait = bpy.data.images.load(PORTRAIT, check_existing=True)


def pixels(img):
    w, hh = img.size
    px = np.empty(w * hh * 4, np.float32); img.pixels.foreach_get(px)
    return px.reshape(hh, w, 4)


def raster(res, vals):
    """Per texel of the generated texture: vals (per face, per-corner value vectors) interpolated."""
    uvl = gbm.loops.layers.uv['UVMap']
    C = len(vals[0][0])
    acc = np.zeros((res, res, C), np.float32); hit = np.zeros((res, res), bool)
    for f, fv in zip(gbm.faces, vals):
        if f.material_index == 1:  # the cap: no texture
            continue
        P = np.array([tuple(l[uvl].uv) for l in f.loops]) * res
        A, B, Cc = P
        d = (B[0] - A[0]) * (Cc[1] - A[1]) - (Cc[0] - A[0]) * (B[1] - A[1])
        if abs(d) < 1e-9:
            continue
        x0, y0 = np.floor(P.min(0) - 1).astype(int).clip(0, res - 1)
        x1, y1 = np.ceil(P.max(0) + 1).astype(int).clip(0, res - 1)
        xs, ys = np.meshgrid(np.arange(x0, x1 + 1) + 0.5, np.arange(y0, y1 + 1) + 0.5)
        w0 = ((B[0] - xs) * (Cc[1] - ys) - (Cc[0] - xs) * (B[1] - ys)) / d
        w1 = ((Cc[0] - xs) * (A[1] - ys) - (A[0] - xs) * (Cc[1] - ys)) / d
        w2 = 1 - w0 - w1
        eps = 1.5 / max(1.0, np.abs(P - P.mean(0)).max())
        ins = (w0 > -eps) & (w1 > -eps) & (w2 > -eps)
        if not ins.any():
            continue
        V = np.array(fv, np.float32)
        val = w0[..., None] * V[0] + w1[..., None] * V[1] + w2[..., None] * V[2]
        yy, xx = ys[ins].astype(int), xs[ins].astype(int)
        acc[yy, xx] = val[ins]; hit[yy, xx] = True
    for _ in range(4):  # grow into the gutters
        for dy, dx in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            sh = np.roll(np.roll(hit, dy, 0), dx, 1) & ~hit
            acc[sh] = np.roll(np.roll(acc, dy, 0), dx, 1)[sh]
            hit = hit | sh
    return acc, hit


def blur(a, r):
    for ax in (0, 1):
        pad = [(r + 1, r) if i == ax else (0, 0) for i in range(a.ndim)]
        c = np.cumsum(np.pad(a, pad, mode='edge'), axis=ax)
        n = c.shape[ax]
        a = (np.take(c, range(2 * r + 1, n), axis=ax) - np.take(c, range(0, n - 2 * r - 1), axis=ax)) / (2 * r + 1)
    return a


LUM = np.array([0.2126, 0.7152, 0.0722], np.float32)


def recolour():
    """Skin: brightness and hue of the portrait's skin (measured on skin facing the camera), keeping CHROMA_KEEP of the
    texture's own variation - the generated skin is darker, more orange and blotchy. Hair: the portrait's hair colour,
    the red blotches toned down. Shading baked into the texture (dark eye sockets, the shadowed side of the face, ears
    and under them) taken out: per vertex the texture's brightness, smoothed over the mesh, is the light that fell
    there; the texels are divided by it (fine detail - wrinkles, strands - stays). Skin or hair: the faces' classes
    smoothed over the mesh (stray 'hair' faces on the cheeks don't show). Dark bags under the eyes lightened.
    Returns the neck's colour: the finished skin's (sRGB)."""
    gpx, ppx = pixels(gimg), pixels(portrait)
    res = gimg.size[0]
    uvl = gbm.loops.layers.uv['UVMap']
    g, p = [], []
    for f in gbm.faces:
        if is_skin(f) and f.normal.dot(FWD) > 0.85 and f.calc_center_median().z > CHIN_Z:
            q = f.loops[0][puv].uv
            pc = ppx[min(1023, int(q.y * 1024)), min(1023, int(q.x * 1024))]
            u = f.loops[0][uvl].uv
            if pc[3] > 0.5:
                g.append(gpx[min(res - 1, int(u.y * res)), min(res - 1, int(u.x * res)), :3]); p.append(pc[:3])
    g, p = np.median(np.array(g), 0), np.median(np.array(p), 0)
    ph = portrait_hair(ppx)
    rgb = gpx[..., :3].copy()
    L = rgb @ LUM
    # per vertex: hair (classes smoothed) and the texture's brightness, low-passed over the mesh
    gbm.verts.index_update()
    n = len(gbm.verts)
    nb = [[e.other_vert(v).index for e in v.link_edges] for v in gbm.verts]
    hv = np.array([np.mean([is_hair(f) for f in v.link_faces]) if v.link_faces else 0.0 for v in gbm.verts])
    lv, cnt = np.zeros(n), np.zeros(n)
    for f in gbm.faces:
        if f.material_index == 1:
            continue
        for l in f.loops:
            u = l[uvl].uv
            lv[l.vert.index] += L[min(res - 1, int(u.y * res)), min(res - 1, int(u.x * res))]; cnt[l.vert.index] += 1
    lv /= np.maximum(cnt, 1)

    def smooth(a, it, w=None):
        w = np.ones(n) if w is None else w
        a = a.copy()
        for _ in range(it):
            num = np.array([a[i] * w[i] + sum(a[j] * w[j] for j in nb[i]) for i in range(n)])
            den = np.array([w[i] + sum(w[j] for j in nb[i]) for i in range(n)])
            a = np.where(den > 1e-6, num / np.maximum(den, 1e-6), a)
        return a

    hv = smooth(hv, 4)
    hard = np.clip((hv - 0.3) / 0.4, 0, 1)
    l_skin = smooth(lv, DELIGHT_IT, 1 - hard + 1e-3)
    l_hair = smooth(lv, DELIGHT_IT, hard + 1e-3)
    skin_l0, hair_l0 = float(np.median(lv[hard < 0.1])), float(np.median(lv[hard > 0.9]))
    f_skin = np.clip(skin_l0 / np.maximum(l_skin, 1e-3), *DELIGHT_CLAMP)
    f_hair = np.clip(1 + (hair_l0 / np.maximum(l_hair, 1e-3) - 1) * DELIGHT_HAIR, *DELIGHT_CLAMP)
    vals = []
    for f in gbm.faces:
        fr = smoothstep(f.normal.dot(FWD), 0.5, 0.8)  # the portrait's coordinates hold for the front only
        vals.append([(l[puv].uv.x * 1024, (1 - l[puv].uv.y) * 1024, fr, hard[l.vert.index], f_skin[l.vert.index],
                      f_hair[l.vert.index], rim_fill(l.vert)) for l in f.loops])
    acc, hit = raster(res, vals)
    hair_w = acc[..., 3:4]
    skin_w = 1 - hair_w
    chroma = rgb / np.maximum(L, 1e-4)[..., None]

    def towards(ref_g, ref_p, keep):
        lg, lp = max(float(ref_g @ LUM), 1e-4), max(float(ref_p @ LUM), 1e-4)
        return np.clip((ref_p / lp + (chroma - ref_g / lg) * keep) * (L * lp / lg)[..., None], 0, 1)

    # the painted eyes keep their own light and dark
    ix, iy = acc[..., 0], acc[..., 1]
    eye = np.zeros(ix.shape, np.float32)
    for rims in EYE_RIMS.values():
        xs = np.array([q[0] for q in rims['upper']]); yu = np.array([q[1] for q in rims['upper']])
        yl = np.array([q[1] for q in rims['lower']])
        ou, ol = np.argsort(xs), np.argsort([q[0] for q in rims['lower']])
        a = np.interp(ix, xs[ou], yu[ou]) - 3
        b = np.interp(ix, np.array([q[0] for q in rims['lower']])[ol], yl[ol]) + 3
        inside = (iy > a) & (iy < b) & (ix > xs.min()) & (ix < xs.max())
        eye = np.maximum(eye, inside.astype(np.float32))
    eye = blur(eye * acc[..., 2], 3)[..., None]
    fs = 1 + (acc[..., 4:5] - 1) * (1 - eye)
    skin_rgb = np.clip(towards(g, p, CHROMA_KEEP) * fs, 0, 1)
    hg = np.median(rgb[(hair_w[..., 0] > 0.99) & hit], 0)
    hair_rgb = np.clip(towards(hg, ph, HAIR_KEEP) * acc[..., 5:6], 0, 1)
    out = np.where(hit[..., None], skin_rgb * skin_w + hair_rgb * hair_w, rgb)
    # bags under the eyes: brightness up towards the skin's, where darker (hue kept)
    bag = np.zeros(ix.shape, np.float32)
    for rims in EYE_RIMS.values():
        lo = rims['lower']
        xs = np.array([q[0] for q in lo]); ys = np.array([q[1] for q in lo])
        order = np.argsort(xs)
        yl = np.interp(ix, xs[order], ys[order])
        d = iy - yl
        side = np.clip(1 - np.maximum(xs.min() - ix, ix - xs.max()) / 12, 0, 1)
        bag = np.maximum(bag, (d > 0) * (1 - np.clip((d - UNDER_EYE[0]) / (UNDER_EYE[1] - UNDER_EYE[0]), 0, 1)) * side)
    bag *= acc[..., 2]
    lo_ = out @ LUM; want = float(p @ LUM) * 0.95
    k = np.where(lo_ < want, (want / np.maximum(lo_, 1e-4) - 1) * bag * UNDER_EYE[2] + 1, 1)[..., None]
    out = np.clip(out * k, 0, 1)
    # the neck takes the colour of the skin just above the cut (jaw and chin), so the two meet unseen
    near = hit & (skin_w[..., 0] > 0.95) & (acc[..., 6] > 0.05)
    neck_rgb = np.median(out[near], 0) if near.sum() > 50 else np.median(out[hit & (skin_w[..., 0] > 0.95)], 0)
    img = bpy.data.images.get('head_albedo') or bpy.data.images.new('head_albedo', res, res)
    img.scale(res, res)
    px = np.concatenate([out, np.ones_like(out[..., :1])], axis=2).astype(np.float32)
    img.pixels.foreach_set(px.ravel())
    img.filepath_raw = SKIN_TEX; img.file_format = 'PNG'; img.save()
    print('colour: generated skin %s portrait %s, hair %s portrait %s; delight x%.2f..%.2f' % (
        np.round(g, 2), np.round(p, 2), np.round(hg, 2), np.round(ph, 2), f_skin.min(), f_skin.max()))
    return neck_rgb * NECK_SHADE


def rim_fill(v):
    """How close to the cut under the jaw (1 at the rim): where the neck's colour is measured."""
    if v.co.z > CHIN_Z + 0.005:
        return 0.0
    return 1 - smoothstep(RIM_KD.find(v.co)[2], RIM_FILL[0], RIM_FILL[1])


def portrait_hair(ppx):
    """Median colour of the hair in head_input.png: dark brown pixels of the head above the eyes."""
    top = min(min(y for _, y in r['upper']) for r in EYE_RIMS.values())
    a = ppx[::-1][:int(top) - 20]  # rows from the top of the picture
    a = a[a[..., 3] > 0.5][:, :3]
    v = a.max(1)
    hue_ok = (a[:, 0] > a[:, 1]) & (a[:, 1] > a[:, 2])
    hair = a[(v < 0.55) & (v > 0.08) & hue_ok]
    return np.median(hair, 0)


NECK_RGB = recolour()  # before refine: the measured skin is not skewed towards the denser eyes


def smooth_cap():
    """The cap under the jaw, flat and faceted as filled: subdivided inside (not along the rim) and laid onto MPFB's
    jaw and neck. (After the texture: the cap has none.)"""
    cap = {f for f in gbm.faces if f.material_index == 1}
    for _ in range(CAP_SUBDIV):
        inner = [e for e in {e for f in cap for e in f.edges} if all(g in cap for g in e.link_faces)]
        bmesh.ops.subdivide_edges(gbm, edges=inner, cuts=1, use_grid_fill=False)
        bmesh.ops.triangulate(gbm, faces=[f for f in gbm.faces if len(f.verts) > 3])
        cap = {f for f in gbm.faces if f.material_index == 1}
    inner_v = {v for f in cap for v in f.verts if all(g in cap for g in v.link_faces)}
    for it in range(8):
        for v in inner_v:
            p = BODY_BVH.find_nearest(v.co, 0.1)[0]
            if p is not None:
                v.co = p
        if it < 7:
            for v in inner_v:
                ns = [e.other_vert(v).co for e in v.link_edges]
                v.co = v.co * 0.5 + sum(ns, Vector()) / len(ns) * 0.5
    gbm.normal_update()
    print('jaw cap: %d faces' % len(cap))


smooth_cap()


refine()
IMG = img_points()


# ---------------------------------------------------------------- eyes: pivots and the blink angle
def img_kd():
    vs = [v for v in gbm.verts if front(v)]
    kd = KDTree(len(vs))
    for i, v in enumerate(vs):
        kd.insert((*IMG[v], 0), i)
    kd.balance()
    return lambda p: vs[kd.find((p[0], p[1], 0))[1]]


at_img = img_kd()
EYE = {}
for s, rims in EYE_RIMS.items():
    up, lo = rims['upper'], rims['lower']
    xs = [p[0] for p in up]
    x0, x1 = min(xs), max(xs)
    opens = [(x, interp(lo, x) - interp(up, x)) for x in range(int(x0), int(x1) + 1)]
    xc, omax = max(opens, key=lambda t: t[1])
    U3, L3 = at_img((xc, interp(up, xc))).co, at_img((xc, interp(lo, xc))).co
    pivot = (U3 + L3) / 2 - FWD * EYE_DEPTH
    ang = lambda p: math.atan2((p - pivot).z, (p - pivot).dot(FWD))  # noqa: E731
    EYE[s] = dict(x0=x0, x1=x1, omax=omax, pivot=pivot, deg=math.degrees(ang(U3) - ang(L3)))
BLINK_DEG = max(e['deg'] for e in EYE.values())
print('eyes: blink %.1f deg (l %.1f, r %.1f)' % (BLINK_DEG, EYE['l']['deg'], EYE['r']['deg']))
add_face_bones({s: e['pivot'] for s, e in EYE.items()}, FWD)
deform = bones | set(head_shape.FACE_BONES)


def lid_weight(v, s):
    """Upper lid weight for a blink of BLINK_DEG: rim to rim it grades so every point lands on the lower rim."""
    e = EYE[s]
    if not front(v):
        return 0.0
    x, y = IMG[v]
    up, lo = EYE_RIMS[s]['upper'], EYE_RIMS[s]['lower']
    if not e['x0'] <= x <= e['x1']:
        return 0.0
    yu, yl = interp(up, x), interp(lo, x)
    scale = e['deg'] / BLINK_DEG  # the narrower eye turns less
    if y > yl:
        return 0.0
    if y >= yu:
        return (yl - y) / e['omax'] * scale
    return (yl - yu) / e['omax'] * scale * (1 - smoothstep(yu - y, 0, LID_FADE))


# ---------------------------------------------------------------- mouth
def lip_s(v):
    """Signed px below the lip line, None outside the mouth."""
    if not front(v):
        return None
    x, y = IMG[v]
    ly = interp(MOUTH_LINE, x)
    return None if ly is None else y - ly


def mouth():
    """The generated mouth is a little open, a tube going in. Lower side (follows the jaw): the lower lip under the
    lip line, and inside the mouth whatever is below the line's height. Returns those verts, its centre, width."""
    ends = [at_img(MOUTH_LINE[0]).co, at_img(MOUTH_LINE[-1]).co]
    pts = [at_img(p).co for p in MOUTH_LINE]
    c = sum(pts, Vector()) / len(pts)
    lower = {}
    hair = {v for f in gbm.faces if f[CLS] == head_shape.HAIR for v in f.verts}
    for v in gbm.verts:
        if v in hair:  # the moustache hangs over the mouth: it stays
            continue
        s = lip_s(v)
        if s is not None:
            if s > 0:
                lower[v] = 1 - smoothstep(s, JAW_FULL * 0.5, JAW_FULL)
        elif (v.co - c).length < 0.03 and (v.co - c).dot(FWD) < 0.0:  # inside: graded about the line's height
            lower[v] = 1 - smoothstep(v.co.z, c.z - 0.003, c.z + 0.003)
    w = (ends[0] - ends[1]).length
    print('mouth: %.1f cm wide' % (w * 100))
    return lower, c, w


LOWER, MOUTH_C, MOUTH_W = mouth()

# ---------------------------------------------------------------- the head object and its weights
for l in [l for l in gbm.loops.layers.uv.values() if l.name != 'UVMap']:
    gbm.loops.layers.uv.remove(l)
gbm.verts.index_update()
FRONT_I = {v.index for v in gbm.verts if front(v)}
LOWER_I = {v.index: k for v, k in LOWER.items()}
HAIR_I = {v.index for f in gbm.faces if is_hair(f) for v in f.verts}
LIDS = {s: {v.index: lid_weight(v, s) for v in gbm.verts} for s in EYE}
LIPS = {v.index: lip_s(v) for v in gbm.verts}
head = new_object('Head', gbm, material('Head_Skin', SKIN_TEX, 0.55))
NECK_LIN = tuple(float(c) for c in np.where(NECK_RGB <= 0.04045, NECK_RGB / 12.92, ((NECK_RGB + 0.055) / 1.055) ** 2.4))
head.data.materials.append(material('Head_Neck', None, 0.55, NECK_LIN))  # the cap under the jaw
gbm.free()

src_bm = bmesh.new(); src_bm.from_mesh(full)
src_bm.verts.ensure_lookup_table()
bmesh.ops.delete(src_bm, geom=[v for v in src_bm.verts if v.index not in body], context='VERTS')
src = new_object('WeightSource', src_bm, material('WeightSource'), gnames)
src_bm.free()
for n in gnames:
    if n in deform:
        head.vertex_groups.new(name=n)
for n in head_shape.FACE_BONES:
    if not head.vertex_groups.get(n):
        head.vertex_groups.new(name=n)
dt = head.modifiers.new('W', 'DATA_TRANSFER')
dt.object = src; dt.use_vert_data = True; dt.data_types_verts = {'VGROUP_WEIGHTS'}
dt.vert_mapping = 'POLYINTERP_NEAREST'; dt.layers_vgroup_select_src = 'ALL'; dt.layers_vgroup_select_dst = 'NAME'
head.modifiers.move(len(head.modifiers) - 1, 0)
bpy.context.view_layer.objects.active = head
bpy.ops.object.modifier_apply(modifier='W')
bpy.data.objects.remove(src)


def set_weights():
    """Transferred MPFB weights, then: no eye, lid or lip-corner bones (painted eyes, one cut mouth); the upper lids
    from lid_weight; jaw: nothing above the lip line or on the moustache, everything just under the cut; 'head' takes
    what is left."""
    vg = head.vertex_groups
    names = [g.name for g in vg]
    mouth_z = MOUTH_C.z
    for v in head.data.vertices:
        w = {names[g.group]: g.weight for g in v.groups if g.weight > 0}
        tot = sum(w.values()) or 1.0
        w = {k: x / tot for k, x in w.items() if not k.startswith(('eye_', 'lid_', 'lip_corner_'))}
        s = LIPS[v.index]
        jaw = w.get('jaw', 0.0)
        if v.index in LOWER_I:
            jaw = max(jaw, LOWER_I[v.index]) if s is not None else LOWER_I[v.index]
        elif (s is not None and s <= 0.5) or (v.index in HAIR_I and v.index in FRONT_I and v.co.z > mouth_z - 0.02):
            jaw = 0.0
        w['jaw'] = jaw
        for side in EYE:
            if LIDS[side][v.index] > 0:
                w['lid_upper_' + side] = LIDS[side][v.index]
        rest = sum(x for k, x in w.items() if k != 'head')
        if rest > 1:
            w = {k: x / rest for k, x in w.items() if k != 'head'}
        else:
            w['head'] = 1 - rest
        for g in list(v.groups):
            vg[g.group].remove([v.index])
        for k, x in w.items():
            if x > 1e-4:
                vg[k].add([v.index], x, 'REPLACE')


set_weights()


def close_mouth():
    """The generated mouth is a little open, his lips are closed: the lower lip raised up to the moustache (rest shape),
    the skin under it following less and less down to the chin; inside the mouth its lower side."""
    for v in head.data.vertices:
        s = LIPS[v.index]
        if s is not None:
            k = 0.0 if v.index in HAIR_I or s <= 0 else 1 - smoothstep(s, CLOSE_FADE[0], CLOSE_FADE[1])
        else:
            k = LOWER_I.get(v.index, 0.0)
        v.co.z += MOUTH_CLOSE * k


close_mouth()


# ---------------------------------------------------------------- mouth cavity
def mouth_bag():
    b = bmesh.new()
    bmesh.ops.create_uvsphere(b, u_segments=16, v_segments=10, radius=1.0)
    c = MOUTH_C - FWD * (MOUTH_BACK + 0.010)  # its front MOUTH_BACK behind the lips
    side = FWD.cross(Vector((0, 0, 1))).normalized()
    M = Matrix((side * MOUTH_W * 0.45, FWD * 0.010, Vector((0, 0, 0.012)))).transposed()
    for v in b.verts:
        v.co = c + M @ v.co
    ob = new_object('Mouth', b, material('Head_Mouth', None, 0.5, MOUTH_RGB), deform)
    b.free()
    for v in ob.data.vertices:
        k = smoothstep(v.co.z, c.z - 0.006, c.z + 0.006)
        ob.vertex_groups['head'].add([v.index], k, 'REPLACE')
        ob.vertex_groups['jaw'].add([v.index], 1 - k, 'REPLACE')


mouth_bag()

# ---------------------------------------------------------------- neck: MPFB's, from the collar up into the head
HEADISH = {'head', 'neck_01'} | set(head_shape.FACE_BONES)


def neck():
    """MPFB's (fitted) neck in the skin's colour, up to just under the chin, where it runs inside the generated head:
    wherever it would show through the head it is tucked NECK_TUCK under its surface."""
    b = bmesh.new(); b.from_mesh(full)
    dl = b.verts.layers.deform.active
    keep = [f for f in b.faces if all(v.index in body and HEAD_Z < v.co.z < CHIN_Z + 0.005 and
                                      sum(w for g, w in v[dl].items() if gnames[g] in HEADISH) > 0.5 for v in f.verts)]
    ks = set(keep)
    bmesh.ops.delete(b, geom=[f for f in b.faces if f not in ks], context='FACES')
    bmesh.ops.delete(b, geom=[v for v in b.verts if not v.link_faces], context='VERTS')
    hb = bmesh.new(); hb.from_mesh(head.data)
    hbvh = BVHTree.FromBMesh(hb)
    hb.free()
    for v in b.verts:
        if (v.co - CUT[0]).dot(CUT[1]) < 0.002:  # under the head: its own
            continue
        p, n, _, _ = hbvh.find_nearest(v.co, 0.03)
        if p is not None and (v.co - p).dot(n) > -NECK_TUCK:
            v.co = p - n * NECK_TUCK
    ob = new_object('Neck', b, material('Head_Neck', None, 0.55, NECK_LIN), gnames)
    b.free()
    for g in list(ob.vertex_groups):
        if g.name not in deform:
            ob.vertex_groups.remove(g)
    print('neck: %d faces' % len(ob.data.polygons))


neck()

# ---------------------------------------------------------------- the body no longer carries the head
under = bpy.data.objects['BodyUnder']
ub = bmesh.new(); ub.from_mesh(under.data)
udl = ub.verts.layers.deform.active
ugn = [g.name for g in under.vertex_groups]
gone = [f for f in ub.faces if all(v.co.z > HEAD_Z + 0.01 and sum(w for g, w in v[udl].items() if ugn[g] in HEADISH) > 0.5
                                   for v in f.verts)]
bmesh.ops.delete(ub, geom=gone, context='FACES')
bmesh.ops.delete(ub, geom=[v for v in ub.verts if not v.link_faces], context='VERTS')
ub.to_mesh(under.data); ub.free()

hd = dict(sc['head']); hd['BLINK_DEG'] = BLINK_DEG; sc['head'] = hd
